CREATE TABLE IF NOT EXISTS discipline_ledger (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tournament_id BIGINT UNSIGNED NOT NULL,person_id BIGINT UNSIGNED NULL,team_id BIGINT UNSIGNED NULL,match_id BIGINT UNSIGNED NULL,event_id BIGINT UNSIGNED NULL,card_type VARCHAR(30) NOT NULL,card_units INT NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,INDEX discipline_person(tournament_id,person_id,status),FOREIGN KEY(tournament_id) REFERENCES tournaments(id),FOREIGN KEY(person_id) REFERENCES people(id) ON DELETE SET NULL,FOREIGN KEY(team_id) REFERENCES teams(id) ON DELETE SET NULL,FOREIGN KEY(match_id) REFERENCES matches(id) ON DELETE SET NULL,FOREIGN KEY(event_id) REFERENCES match_events(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS suspension_fulfillments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,suspension_id BIGINT UNSIGNED NOT NULL,match_id BIGINT UNSIGNED NOT NULL,served_at DATETIME NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY suspension_match(suspension_id,match_id),FOREIGN KEY(suspension_id) REFERENCES suspensions(id),FOREIGN KEY(match_id) REFERENCES matches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE team_penalties ADD COLUMN revoked_at DATETIME NULL AFTER deleted_at, ADD COLUMN revoked_by BIGINT UNSIGNED NULL AFTER revoked_at, ADD COLUMN appeal_note TEXT NULL AFTER revoked_by;
